/* The start of every C file generated by kojic: the runtime functions (implemented in Rust,
   in the koji_runtime library) and the operators that panic. */

#include <math.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

typedef struct KojiString KojiString;

KojiString *koji_string_new(const char *bytes, size_t length);
void koji_string_retain(const KojiString *string);
void koji_string_release(KojiString *string);
KojiString *koji_string_concat(const KojiString *a, const KojiString *b);
KojiString *koji_string_repeat(const KojiString *string, int64_t count);
bool koji_string_equal(const KojiString *a, const KojiString *b);
int32_t koji_string_compare(const KojiString *a, const KojiString *b);
KojiString *koji_string_from_int(int64_t value);
KojiString *koji_string_from_float(double value);
KojiString *koji_string_from_bool(bool value);

KojiString *koji_string_repr(const KojiString *string);
int64_t koji_string_length(const KojiString *string);
bool koji_string_contains(const KojiString *haystack, const KojiString *needle);

typedef struct KojiList KojiList;

/* How the generated code describes the items of a list (see runtime/src/list.rs). */
typedef struct {
    size_t size;
    void (*retain)(const void *slot);
    void (*release)(const void *slot);
    KojiString *(*repr)(const void *slot);
    bool (*equal)(const void *a, const void *b);
    int32_t (*compare)(const void *a, const void *b);
} KojiElementType;

KojiList *koji_list_new(const KojiElementType *element, size_t capacity);
void koji_list_retain(const KojiList *list);
void koji_list_release(KojiList *list);
int64_t koji_list_length(const KojiList *list);
const void *koji_list_get(const KojiList *list, int64_t index, const char *location);
void *koji_list_slot(KojiList **variable, int64_t index, const char *location);
void koji_list_set(KojiList **variable, int64_t index, const void *value, const char *location);
void koji_list_push(KojiList **variable, const void *value);
void koji_list_insert(KojiList **variable, int64_t index, const void *value, const char *location);
void koji_list_sort(KojiList **variable);
KojiList *koji_list_concat(const KojiList *a, const KojiList *b);
KojiList *koji_list_slice(const KojiList *list, bool has_start, int64_t start, bool has_end,
                          int64_t end, const char *location);
bool koji_list_equal(const KojiList *a, const KojiList *b);
bool koji_list_contains(const KojiList *list, const void *value);
KojiString *koji_list_repr(const KojiList *list);
KojiString *koji_list_join(const KojiList *list, const KojiString *separator);

bool koji_list_pop(KojiList **variable, void *out);
bool koji_list_remove(KojiList **variable, int64_t index, void *out);
int64_t koji_list_index_of(const KojiList *list, const void *value);

typedef struct KojiRecord KojiRecord;

typedef struct {
    const char *name;
    size_t field_count;
    const char *const *field_names;
    const KojiElementType *const *field_types;
} KojiVariantType;

typedef struct {
    size_t variant_count;
    const KojiVariantType *variants;
} KojiRecordType;

KojiRecord *koji_record_new(const KojiRecordType *type, size_t tag);
void koji_record_init(KojiRecord *record, size_t index, const void *value);
void koji_record_retain(const KojiRecord *record);
void koji_record_release(KojiRecord *record);
int64_t koji_record_tag(const KojiRecord *record);
const void *koji_record_get(const KojiRecord *record, size_t index);
void *koji_record_slot(KojiRecord **variable, size_t index);
void koji_record_set(KojiRecord **variable, size_t index, const void *value);
bool koji_record_equal(const KojiRecord *a, const KojiRecord *b);
KojiString *koji_record_repr(const KojiRecord *record);

_Noreturn void koji_fail(const char *location, const KojiString *message);
void koji_print(const KojiString *text, const char *location);
_Noreturn void koji_panic(const char *location, const char *message);
_Noreturn void koji_panic_shift(const char *location, int64_t amount);
int64_t koji_int_pow(int64_t base, int64_t exponent, const char *location);
double koji_float_pow(double base, double exponent, const char *location);

/* Writes a string variable: the new value is already owned, the old one is released. */
static inline void koji_string_set(KojiString **variable, KojiString *value) {
    KojiString *old = *variable;
    *variable = value;
    koji_string_release(old);
}

/* A new reference to a string that is still owned elsewhere. */
static inline KojiString *koji_string_share(KojiString *string) {
    koji_string_retain(string);
    return string;
}

static inline void koji_list_set_variable(KojiList **variable, KojiList *value) {
    KojiList *old = *variable;
    *variable = value;
    koji_list_release(old);
}

static inline KojiList *koji_list_share(KojiList *list) {
    koji_list_retain(list);
    return list;
}

static inline void koji_record_set_variable(KojiRecord **variable, KojiRecord *value) {
    KojiRecord *old = *variable;
    *variable = value;
    koji_record_release(old);
}

static inline KojiRecord *koji_record_share(KojiRecord *record) {
    koji_record_retain(record);
    return record;
}

/* The items of lists and the fields of records, by type. */

static int32_t koji_order(bool less, bool greater) { return less ? -1 : greater ? 1 : 0; }

static KojiString *koji_repr_int(const void *slot) { return koji_string_from_int(*(const int64_t *)slot); }
static bool koji_equal_int(const void *a, const void *b) { return *(const int64_t *)a == *(const int64_t *)b; }
static int32_t koji_compare_int(const void *a, const void *b) {
    int64_t x = *(const int64_t *)a, y = *(const int64_t *)b;
    return koji_order(x < y, x > y);
}
static const KojiElementType koji_element_int = {
    sizeof(int64_t), NULL, NULL, koji_repr_int, koji_equal_int, koji_compare_int};

static KojiString *koji_repr_float(const void *slot) { return koji_string_from_float(*(const double *)slot); }
static bool koji_equal_float(const void *a, const void *b) { return *(const double *)a == *(const double *)b; }
static int32_t koji_compare_float(const void *a, const void *b) {
    double x = *(const double *)a, y = *(const double *)b;
    return koji_order(x < y, x > y);
}
static const KojiElementType koji_element_float = {
    sizeof(double), NULL, NULL, koji_repr_float, koji_equal_float, koji_compare_float};

static KojiString *koji_repr_bool(const void *slot) { return koji_string_from_bool(*(const bool *)slot); }
static bool koji_equal_bool(const void *a, const void *b) { return *(const bool *)a == *(const bool *)b; }
/* Like the interpreter, booleans keep their order when sorted. */
static int32_t koji_compare_bool(const void *a, const void *b) { (void)a; (void)b; return 0; }
static const KojiElementType koji_element_bool = {
    sizeof(bool), NULL, NULL, koji_repr_bool, koji_equal_bool, koji_compare_bool};

static void koji_retain_string(const void *slot) { koji_string_retain(*(KojiString *const *)slot); }
static void koji_release_string(const void *slot) { koji_string_release(*(KojiString *const *)slot); }
static KojiString *koji_repr_string(const void *slot) { return koji_string_repr(*(KojiString *const *)slot); }
static bool koji_equal_string(const void *a, const void *b) {
    return koji_string_equal(*(KojiString *const *)a, *(KojiString *const *)b);
}
static int32_t koji_compare_string(const void *a, const void *b) {
    return koji_string_compare(*(KojiString *const *)a, *(KojiString *const *)b);
}
static const KojiElementType koji_element_string = {
    sizeof(KojiString *), koji_retain_string, koji_release_string, koji_repr_string,
    koji_equal_string, koji_compare_string};

static void koji_retain_list(const void *slot) { koji_list_retain(*(KojiList *const *)slot); }
static void koji_release_list(const void *slot) { koji_list_release(*(KojiList *const *)slot); }
static KojiString *koji_repr_list(const void *slot) { return koji_list_repr(*(KojiList *const *)slot); }
static bool koji_equal_list(const void *a, const void *b) {
    return koji_list_equal(*(KojiList *const *)a, *(KojiList *const *)b);
}
static const KojiElementType koji_element_list = {
    sizeof(KojiList *), koji_retain_list, koji_release_list, koji_repr_list, koji_equal_list, NULL};

static void koji_retain_record(const void *slot) { koji_record_retain(*(KojiRecord *const *)slot); }
static void koji_release_record(const void *slot) { koji_record_release(*(KojiRecord *const *)slot); }
static KojiString *koji_repr_record(const void *slot) { return koji_record_repr(*(KojiRecord *const *)slot); }
static bool koji_equal_record(const void *a, const void *b) {
    return koji_record_equal(*(KojiRecord *const *)a, *(KojiRecord *const *)b);
}
static const KojiElementType koji_element_record = {
    sizeof(KojiRecord *), koji_retain_record, koji_release_record, koji_repr_record, koji_equal_record, NULL};

static inline int64_t koji_int_add(int64_t a, int64_t b, const char *location) {
    int64_t result;
    if (__builtin_add_overflow(a, b, &result)) koji_panic(location, "integer overflow");
    return result;
}

static inline int64_t koji_int_sub(int64_t a, int64_t b, const char *location) {
    int64_t result;
    if (__builtin_sub_overflow(a, b, &result)) koji_panic(location, "integer overflow");
    return result;
}

static inline int64_t koji_int_mul(int64_t a, int64_t b, const char *location) {
    int64_t result;
    if (__builtin_mul_overflow(a, b, &result)) koji_panic(location, "integer overflow");
    return result;
}

/* Truncates toward zero, like Go and Rust. */
static inline int64_t koji_int_div(int64_t a, int64_t b, const char *location) {
    if (b == 0) koji_panic(location, "division by zero");
    if (a == INT64_MIN && b == -1) koji_panic(location, "integer overflow");
    return a / b;
}

/* The remainder has the sign of the dividend. */
static inline int64_t koji_int_rem(int64_t a, int64_t b, const char *location) {
    if (b == 0) koji_panic(location, "division by zero");
    if (a == INT64_MIN && b == -1) koji_panic(location, "integer overflow");
    return a % b;
}

static inline int64_t koji_int_neg(int64_t a, const char *location) {
    if (a == INT64_MIN) koji_panic(location, "integer overflow");
    return -a;
}

static inline int64_t koji_shift_left(int64_t a, int64_t b, const char *location) {
    if (b < 0 || b >= 64) koji_panic_shift(location, b);
    return (int64_t)((uint64_t)a << b);
}

static inline int64_t koji_shift_right(int64_t a, int64_t b, const char *location) {
    if (b < 0 || b >= 64) koji_panic_shift(location, b);
    return a >> b;
}

/* float has no infinity: a result that does not fit is a representation limit. */
static inline double koji_float_check(double result, const char *location) {
    if (!isfinite(result)) koji_panic(location, "float overflow");
    return result;
}

static inline double koji_float_div(double a, double b, const char *location) {
    if (b == 0.0) koji_panic(location, "division by zero");
    return koji_float_check(a / b, location);
}

static inline double koji_float_rem(double a, double b, const char *location) {
    if (b == 0.0) koji_panic(location, "division by zero");
    return koji_float_check(fmod(a, b), location);
}

/* One step of `for i in range(...)`. */
static inline bool koji_range_next(int64_t *next, int64_t end, int64_t step, bool *done,
                                   int64_t *value) {
    int64_t i = *next;
    if (*done || !((step > 0 && i < end) || (step < 0 && i > end))) return false;
    if (__builtin_add_overflow(i, step, next)) *done = true;
    *value = i;
    return true;
}
